import * as crypto from "node:crypto";
function main(): void {
  const hex = (x: Uint8Array | ArrayBuffer): string => Array.from(new Uint8Array(x as any)).map((b) => b.toString(16).padStart(2, "0")).join("");
  console.log(hex(crypto.hkdfSync("sha256", "key", "salt", "info", 16) as any));
  console.log(hex(crypto.hkdfSync("sha512", Buffer.from("k"), "", "", 70) as any));
  console.log(crypto.getCiphers().includes("aes-256-cbc"), crypto.getCiphers().length > 50);
  console.log(crypto.getHashes().includes("sha256"), crypto.getHashes().includes("sha3-256"), crypto.getHashes().length);
}
